"""1405 (#11 emily_far_reach_pull_variants): Test-CarryBody-v1380.ps1 with the Far Reach body pull held and filmed. In 1380b
Emily's Far Reach pulled the choked body (power_grapple_pull pullIn, pull, pullOut: variants 7-9) but LT was released after
0.9 s, so the pull ended before the body reached her and the native grab_corpse catch never ran; the observer did not
frame her. Now LT is held 2.6 s per try (the pull continues while it is held), and before the first try the observer's
free camera is held 3.6 m to the side of the pull line, at its midpoint, 1.6 m up, looking at it; both windows are
recorded through the tries (farreach-source.mp4, farreach-observer.mp4). Generated by make_carry_body_v1405.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Test-CarryBody-v1380.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)

rep("# 1380 (#11):", "# 1405 (#11): the Far Reach body pull is held 2.6 s and filmed from beside the pull line. Generated by make_carry_body_v1405.py.\n# 1380 (#11):")
rep("     for($t=0;$t-lt2;$t++){try{& \"$PSScriptRoot/Set-ObserverPitch.ps1\" -Role $source -Pitch 20 -Quick|Out-Null;break}catch{Start-Sleep -Milliseconds 300}}\n"
    "     $fm=Start-Process",
    "     for($t=0;$t-lt2;$t++){try{& \"$PSScriptRoot/Set-ObserverPitch.ps1\" -Role $source -Pitch 20 -Quick|Out-Null;break}catch{Start-Sleep -Milliseconds 300}}\n"
    "     $mx=([double]$gp[0]+$fx2)/2;$my=([double]$gp[1]+$fy2)/2;$hx=$mx-3.6*$dy/$dl;$hy=$my+3.6*$dx/$dl;$hz=[double]$me[2]+1.6\n"
    "     $hyaw=[Math]::Atan2($my-$hy,$mx-$hx)*180/[Math]::PI;$row.farReachCamera=@($hx,$hy,$hz,$hyaw)\n"
    "     try{C $peer 'coop_observer_camera off';$op=(Q $peer '--player-states').position\n"
    "      C $peer ('setviewpos {0} {1} {2} {3} 0' -f (F $op[0]),(F $op[1]),(F ([double]$op[2]+1.7)),$hyaw.ToString('F4',$inv));Start-Sleep -Milliseconds 300\n"
    "      & \"$PSScriptRoot/Set-ObserverPitch.ps1\" -Role $peer -Pitch 12 -Quick|Out-Null\n"
    "      C $peer ('coop_observer_camera hold_at {0} {1} {2}' -f (F $hx),(F $hy),(F $hz));Start-Sleep -Milliseconds 400;$row.farReachCameraHeld=(S $peer '.observer-camera.json').active}catch{$row.farReachCameraError=$_.Exception.Message}\n"
    "     $frCaptures=@();foreach($pair in @(@($source,'source'),@($peer,'observer'))){$hwnd=(Get-Process -Id $pids[$pair[0]]).MainWindowHandle.ToInt64()\n"
    "      $frCaptures+=Start-Process (Get-Command ffmpeg).Source -ArgumentList @('-hide_banner','-loglevel','warning','-nostdin','-f','lavfi','-i',\"gfxcapture=hwnd=${hwnd}:capture_cursor=0:max_framerate=30:width=-2:height=-2,hwdownload,format=bgra\",'-t','16','-an','-c:v','libx264','-preset','veryfast','-crf','18','-pix_fmt','yuv420p','-fps_mode','passthrough','-movflags','+faststart',\"$out/$key-farreach-$($pair[1]).mp4\") -WindowStyle Hidden -RedirectStandardError \"$out/$key-farreach-$($pair[1])-capture.log\" -RedirectStandardOutput \"$out/$key-farreach-$($pair[1])-capture.stdout\" -PassThru}\n"
    "     $fm=Start-Process")
rep("     for($k=0;$k-lt3-and!$carrying;$k++){& \"$lab/Send-D2Input.ps1\" -Role $source -LeftTrigger 255 -DurationMs 900|Out-Null;Start-Sleep -Milliseconds 2600\n",
    "     for($k=0;$k-lt3-and!$carrying;$k++){& \"$lab/Send-D2Input.ps1\" -Role $source -LeftTrigger 255 -DurationMs 2600|Out-Null;Start-Sleep -Milliseconds 1800\n")
rep("     $row.farReachCarry=$carrying;$me=try{(Q $source '--player-states').position}catch{$me};if(!$fm.WaitForExit(14000)){Stop-Process -Id $fm.Id}};",
    "     $row.farReachCarry=$carrying;$me=try{(Q $source '--player-states').position}catch{$me};if(!$fm.WaitForExit(14000)){Stop-Process -Id $fm.Id}\n"
    "     foreach($c in $frCaptures){try{if(!$c.WaitForExit(20000)){Stop-Process -Id $c.Id}}catch{}};$row.farReachRecorded=@($frCaptures).Count};")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Test-CarryBody-v1405.ps1').write_bytes(out.encode('utf-8'))
print('ok')
